<div class="dash-card"><input id="tk-search" placeholder="Cari nama, NIP, jabatan, atau status" style="margin-bottom:12px"><div class="sp-table-wrap"><table class="realisasi"><thead><tr><th>Nama</th><th>NIP</th><th>Golongan/Pangkat</th><th>Jabatan</th><th>Pasangan</th><th>Anak Aktif</th><th>Status</th></tr></thead><tbody>@forelse($dashboard['rincian'] as $i=>$r)<tr class="tk-row" data-row="{{ $i }}"><td><strong>&#9656; {{ $r['nama'] }}</strong></td><td>{{ $r['nip'] }}</td><td>{{ $r['golongan'] }} / {{ $r['pangkat'] }}</td><td>{{ $r['jabatan'] }}</td><td>{{ $r['pasangan'] ?: 'Tidak' }}</td><td>{{ $r['jumlah_anak_aktif'] }}</td><td><span class="badge st-aktif">{{ $r['status'] }}</span></td></tr><tr class="tk-detail" data-detail="{{ $i }}"><td colspan="7"><strong>Rincian Anak</strong>@forelse($r['anak'] as $anak)<div style="padding:5px 0;border-bottom:1px dashed var(--line)">{{ $anak['nama'] }} · {{ $anak['tanggal_lahir'] ?: 'Tanggal invalid' }} · {{ $anak['umur']['teks'] ?? '-' }}<br><span style="color:{{ $anak['kelayakan']['aktif']?'var(--ok)':'var(--err)' }}">{{ $anak['kelayakan']['aktif']?'Aktif':'Tidak aktif' }}{{ $anak['kelayakan']['alasan']?' — '.$anak['kelayakan']['alasan']:'' }}</span></div>@empty<div class="sub">Tidak ada anak.</div>@endforelse</td></tr>@empty<tr><td colspan="7" style="text-align:center;padding:30px;color:var(--mut)">Belum ada data tunjangan keluarga.</td></tr>@endforelse</tbody></table></div></div><script>document.querySelectorAll('.tk-row').forEach(r=>r.addEventListener('click',()=>document.querySelector('[data-detail="'+r.dataset.row+'"]').classList.toggle('open')));document.getElementById('tk-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.tk-row').forEach(r=>{const show=r.textContent.toLowerCase().includes(q);r.style.display=show?'':'none';if(!show)document.querySelector('[data-detail="'+r.dataset.row+'"]').classList.remove('open')})});</script>
